  if (dk === w.mainKey || (isStory(w) && dk === w.story.protagonistKey)) { toast(`「${w.entities[dk].title}」은(는) ${isStory(w) ? "주인공" : "대문"} 문서라 다른 문서에 합칠 수 없습니다. 반대로 다른 문서를 이쪽에 합쳐 주세요.`); return; }
