    const list = (Array.isArray(r?.nextChoices) ? r.nextChoices : []).map(x => stripMarks(asText(x)).slice(0, 200)).filter(x => x && !isBroken(x)).slice(0, 3);
    if (!list.length) throw { code: "invalid_json" };
